            .get_connection_unix_user(sender.clone().into())
            .await
            .map_err(|error| format!("D-Bus caller credential lookup failed: {error}"))?;
        if uid != 0 {
            return Err("permission denied: service lifecycle requires uid 0".to_string());
130→        }
